<?php
// ----------------------------------------------------------------------
// VYAS ASTRA — APP & WEBSITE DAILY NOTIFICATION FEED + WEB PUSH DISPATCHER
// Serves real Swiss Ephemeris Panchang, Tyohar/Vrat & Personalized Bhavishyaphal
// generated by the 24x7 Cloud Notification Agent (9:00 PM & 7:00 AM IST).
// ----------------------------------------------------------------------
header("Content-Type: application/json; charset=UTF-8");
header("Access-Control-Allow-Origin: *");
header("Access-Control-Allow-Methods: GET, POST, OPTIONS");

if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {
    http_response_code(200);
    exit();
}

$subscribersFile = __DIR__ . '/../data/push_subscribers.json';
$subscribers = file_exists($subscribersFile) ? json_decode(file_get_contents($subscribersFile), true) : [];
$subCount = is_array($subscribers) ? count($subscribers) : 0;

$feedFile = __DIR__ . '/../data/daily_notifications_feed.json';
$feed = file_exists($feedFile) ? json_decode(file_get_contents($feedFile), true) : null;

// Fallback: fetch live cloud feed from GitHub main branch if local feed is missing
if (!$feed || empty($feed['latest'])) {
    $ctx = stream_context_create(['http' => ['timeout' => 5, 'user_agent' => 'VYAS-Astra/1.0']]);
    $rawRemote = @file_get_contents('https://raw.githubusercontent.com/vyasbilawas-ctrl/vyas-astrology/main/data/daily_notifications_feed.json', false, $ctx);
    if ($rawRemote) {
        $decoded = json_decode($rawRemote, true);
        if (is_array($decoded) && !empty($decoded['latest'])) {
            $feed = $decoded;
        }
    }
}

$slot = $_GET['slot'] ?? $_POST['slot'] ?? 'latest';
$latest = ($slot !== 'latest' && isset($feed['slots'][$slot])) ? $feed['slots'][$slot] : ($feed['latest'] ?? null);

$payload = [
    "title" => $latest['title'] ?? "🕉️ व्यास अस्त्र • दैनिक पंचांग एवं व्यक्तिगत भविष्यफल",
    "body" => $latest['short_body'] ?? "आज का प्रामाणिक पंचांग, नवतारा, सूक्ष्म दशा एवं सर्वतोभद्र चक्र फल देखें।",
    "full_message" => $latest['message'] ?? "",
    "icon" => "/logo_icon.png",
    "badge" => "/logo_icon.png",
    "data" => [
        "url" => "https://vyasastro.in/#daily",
        "date" => $latest['target_date'] ?? date("Y-m-d"),
        "mode" => $latest['mode'] ?? "7am",
        "tithi" => $latest['tithi'] ?? "",
        "festival" => $latest['festival'] ?? "",
        "type" => "daily_panchang_bhavishyaphal"
    ]
];

$action = $_GET['action'] ?? $_POST['action'] ?? 'preview';
echo json_encode([
    "success" => true,
    "action" => $action,
    "updated_at_ist" => $feed['updated_at_ist'] ?? date("c"),
    "subscribers_count" => $subCount,
    "payload" => $payload,
    "slots" => $feed['slots'] ?? [],
    "dispatched_at" => date("c")
], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
